   491→    /// Handle a `LightClientUpdatesByRange` request from the peer.
   492→    fn handle_light_client_updates_by_range_request_inner(
   493→        self: Arc<Self>,
   494→        peer_id: PeerId,
   495→        inbound_request_id: InboundRequestId,
   496→        req: LightClientUpdatesByRangeRequest,
   497→    ) -> Result<(), (RpcErrorResponse, &'static str)> {
   498→        debug!(
   499→            %peer_id,
   500→            count = req.count,
   501→            start_period = req.start_period,
   502→            "Received LightClientUpdatesByRange Request"
   503→        );
   504→
   505→        // Should not send more than max light client updates
   506→        let max_request_size: u64 = req.max_requested();
   507→        if req.count > max_request_size {
   508→            return Err((
   509→                RpcErrorResponse::InvalidRequest,
   510→                "Request exceeded max size",
   511→            ));
   512→        }
   513→
   514→        let lc_updates = match self
   515→            .chain
   516→            .get_light_client_updates(req.start_period, req.count)
   517→        {
   518→            Ok(lc_updates) => lc_updates,
   519→            Err(e) => {
   520→                error!(
   521→                    request = ?req,
   522→                    peer = %peer_id,
   523→                    error = ?e,
   524→                    "Unable to obtain light client updates"
   525→                );
   526→                return Err((RpcErrorResponse::ServerError, "Database error"));
   527→            }
   528→        };
   529→
   530→        for lc_update in lc_updates.iter() {
   531→            self.send_network_message(NetworkMessage::SendResponse {
   532→                peer_id,
   533→                response: Response::LightClientUpdatesByRange(Some(Arc::new(lc_update.clone()))),
   534→                inbound_request_id,
   535→            });
   536→        }
   537→
   538→        let lc_updates_sent = lc_updates.len();
   539→
   540→        if lc_updates_sent < req.count as usize {
   541→            debug!(
   542→                peer = %peer_id,
   543→                info = "Failed to return all requested light client updates. The peer may have requested data ahead of whats currently available",
   544→                start_period = req.start_period,
   545→                requested = req.count,
   546→                returned = lc_updates_sent,
   547→                "LightClientUpdatesByRange outgoing response processed"
   548→            );
   549→        } else {
   550→            debug!(
   551→                peer = %peer_id,
   552→                start_period = req.start_period,
   553→                requested = req.count,
   554→                returned = lc_updates_sent,
   555→                "LightClientUpdatesByRange outgoing response processed"
   556→            );
   557→        }
   558→
   559→        Ok(())
   560→    }
