   990→
   991→    /// Handle a `BlobsByRange` request from the peer.
   992→    fn handle_blobs_by_range_request_inner(
   993→        &self,
   994→        peer_id: PeerId,
   995→        inbound_request_id: InboundRequestId,
   996→        req: BlobsByRangeRequest,
   997→    ) -> Result<(), (RpcErrorResponse, &'static str)> {
   998→        debug!(
   999→            ?peer_id,
  1000→            count = req.count,
  1001→            start_slot = req.start_slot,
  1002→            "Received BlobsByRange Request"
  1003→        );
  1004→
  1005→        let request_start_slot = Slot::from(req.start_slot);
  1006→
  1007→        let data_availability_boundary_slot = match self.chain.data_availability_boundary() {
  1008→            Some(boundary) => boundary.start_slot(T::EthSpec::slots_per_epoch()),
  1009→            None => {
  1010→                debug!("Deneb fork is disabled");
  1011→                return Err((RpcErrorResponse::InvalidRequest, "Deneb fork is disabled"));
  1012→            }
  1013→        };
  1014→
  1015→        let oldest_blob_slot = self
  1016→            .chain
  1017→            .store
  1018→            .get_blob_info()
  1019→            .oldest_blob_slot
  1020→            .unwrap_or(data_availability_boundary_slot);
  1021→        if request_start_slot < oldest_blob_slot {
  1022→            debug!(
  1023→                %request_start_slot,
  1024→                %oldest_blob_slot,
  1025→                %data_availability_boundary_slot,
  1026→                "Range request start slot is older than data availability boundary."
  1027→            );
  1028→
  1029→            return if data_availability_boundary_slot < oldest_blob_slot {
  1030→                Err((
  1031→                    RpcErrorResponse::ResourceUnavailable,
  1032→                    "blobs pruned within boundary",
  1033→                ))
  1034→            } else {
  1035→                Err((
  1036→                    RpcErrorResponse::InvalidRequest,
  1037→                    "Req outside availability period",
  1038→                ))
  1039→            };
  1040→        }
  1041→
  1042→        let block_roots =
  1043→            self.get_block_roots_for_slot_range(req.start_slot, req.count, "BlobsByRange")?;
  1044→
